/// The units of the grammar's numeric values, sorted and lowered.
/// The unit pattern's matcher looks up the word after a number here once.
pub(crate) const UNITS: [&str; 54] = [
    "ch", "cm", "cqb", "cqh", "cqi", "cqmax", "cqmin", "cqw", "deg", "dpcm", "dpi", "dppx", "dvb",
    "dvh", "dvi", "dvw", "em", "ex", "fr", "grad", "hz", "ic", "in", "khz", "lvb", "lvh", "lvi",
    "lvw", "mm", "mozmm", "ms", "pc", "pt", "px", "q", "rad", "rcap", "rch", "rem", "rex", "ric",
    "rlh", "s", "svb", "svh", "svi", "svw", "turn", "vb", "vh", "vi", "vmax", "vmin", "vw",
];

/// The length of the longest of [`UNITS`].
/// A longer word is none of them.
pub(crate) const LONGEST_UNIT: usize = 5;

